package org.eclipse.wb.swing;

import java.awt.Component;
import java.awt.Container;
import java.awt.FocusTraversalPolicy;

/**
 * Cycle through an array of {@link Component}s in order.
 * <p>
 * Generated by Google WindowBuilder / Eclipse. Provides a simple
 * {@link FocusTraversalPolicy} for Swing forms.
 */
public class FocusTraversalOnArray extends FocusTraversalPolicy {
    private final Component m_Components[];

    public FocusTraversalOnArray(Component components[]) {
        m_Components = components;
    }

    private int indexCycle(int index, int delta) {
        int size = m_Components.length;
        int next = (index + delta + size) % size;
        return next;
    }

    private Component cycle(Component currentComponent, int delta) {
        int index = -1;
        for (int i = 0; i < m_Components.length; i++) {
            Component component = m_Components[i];
            if (component == currentComponent) {
                index = i;
                break;
            }
        }
        return index >= 0 ? m_Components[indexCycle(index, delta)] : null;
    }

    @Override
    public Component getComponentAfter(Container container, Component component) {
        return cycle(component, 1);
    }

    @Override
    public Component getComponentBefore(Container container, Component component) {
        return cycle(component, -1);
    }

    @Override
    public Component getFirstComponent(Container container) {
        return m_Components.length > 0 ? m_Components[0] : null;
    }

    @Override
    public Component getLastComponent(Container container) {
        return m_Components.length > 0 ? m_Components[m_Components.length - 1] : null;
    }

    @Override
    public Component getDefaultComponent(Container container) {
        return getFirstComponent(container);
    }
}
